begin;

create extension if not exists pgcrypto with schema extensions;

alter table core.roles drop constraint roles_code_allowed;
alter table core.roles add constraint roles_code_allowed check(code in ('SUPERADMIN','ADMINISTRATIVO','CONTROL_ESCOLAR','CAJA','DOCENTE','PREFECTURA','TUTOR','ALUMNO','ASPIRANTE'));

insert into core.roles(code,display_name,is_system,is_active)
values('PREFECTURA','Prefectura',true,true)
on conflict(code) do update set display_name=excluded.display_name,is_system=true,is_active=true;

create or replace function core.get_current_identity_context()
returns table(auth_user_id uuid,account_id uuid,person_id uuid,account_status core.account_status,role_codes text[],allowed_applications text[],session_valid boolean,mfa_required boolean,mfa_satisfied boolean)
language sql stable security definer set search_path='' as $$
with current_account as(select accounts.* from core.accounts where accounts.auth_user_id=auth.uid()),
accepted as(select coalesce(core.is_current_session_version_valid(),false) session_valid,core.is_mfa_required_for_current_account() mfa_required,core.is_current_mfa_policy_satisfied() mfa_satisfied),
effective_roles as(select coalesce(array_agg(roles.code order by roles.code) filter(where assignments.revoked_at is null and roles.is_active),array[]::text[]) roles from current_account left join core.account_roles assignments on assignments.account_id=current_account.id left join core.roles on roles.id=assignments.role_id)
select auth.uid(),case when accepted.session_valid and accepted.mfa_satisfied then current_account.id end,case when accepted.session_valid and accepted.mfa_satisfied then current_account.person_id end,current_account.account_status,case when accepted.session_valid and accepted.mfa_satisfied then effective_roles.roles else array[]::text[] end,
case when not accepted.session_valid then array[]::text[] else array_remove(array[case when effective_roles.roles&&array['ASPIRANTE','ALUMNO','TUTOR','DOCENTE'] then 'PORTAL_ESCOLAR' end,case when effective_roles.roles&&array['SUPERADMIN','ADMINISTRATIVO','CONTROL_ESCOLAR','PREFECTURA','CAJA'] then 'SISTEMA_ADMINISTRATIVO' end]::text[],null) end,
accepted.session_valid,accepted.mfa_required,accepted.mfa_satisfied from accepted left join current_account on true cross join effective_roles$$;
alter function core.get_current_identity_context() owner to postgres;
revoke execute on function core.get_current_identity_context() from public,anon,authenticated;
grant execute on function core.get_current_identity_context() to authenticated;

create type academic.attendance_session_status as enum ('DRAFT','OPEN','CLOSED','CANCELLED','LOCKED');
create type academic.attendance_status as enum ('NOT_RECORDED','PRESENT','ABSENT','LATE','EXCUSED');
create type academic.lateness_counter_type as enum ('FIRST_PERIOD_VALIDATED','ALL_VALIDATED_LATENESS');
create type academic.lateness_alert_status as enum ('PENDING_NOTIFICATION','NOTIFICATION_RECORDED','ACKNOWLEDGED','CANCELLED');
create type academic.student_permission_type as enum ('LATE_ARRIVAL','EARLY_DEPARTURE','FULL_DAY_ABSENCE','TEMPORARY_EXIT','INSTITUTIONAL_ACTIVITY','OTHER_CONTROLLED');
create type academic.student_permission_status as enum ('DRAFT','SUBMITTED','UNDER_REVIEW','APPROVED','REJECTED','APPLIED','CANCELLED','EXPIRED');
create type academic.permission_reason_code as enum ('MEDICAL','FAMILY','INSTITUTIONAL','TRANSPORTATION','ADMINISTRATIVE','SAFETY','OTHER_PENDING_VALIDATION');
create type academic.permission_validation_status as enum ('APPROVED','REJECTED','REVOKED');
create type academic.attendance_correction_status as enum ('DRAFT','SUBMITTED','UNDER_REVIEW','APPROVED','REJECTED','APPLIED','CANCELLED');
create type academic.attendance_correction_reason as enum ('DATA_ENTRY_ERROR','APPROVED_PERMISSION','WRONG_STUDENT','WRONG_SESSION','PREFECTURE_VALIDATION','ADMINISTRATIVE_CORRECTION');
create type academic.attendance_history_change_type as enum ('INITIAL_CAPTURE','PREFECTURE_VALIDATION','PERMISSION_APPLIED','CONTROLLED_CORRECTION');
create type academic.attendance_event_reason as enum ('INITIAL_CAPTURE','INSTITUTIONAL_VALIDATION','APPROVED_PERMISSION','CONTROLLED_CORRECTION','SESSION_OPERATION','NOTIFICATION_RECORD','VALIDATION_REJECTED');
create type academic.attendance_command_status as enum ('IN_PROGRESS','COMPLETED','FAILED');
create type academic.attendance_command_type as enum ('CREATE_SESSION','OPEN_SESSION','POPULATE_ROSTER','RECORD_ATTENDANCE','RECORD_BULK_ATTENDANCE','CLOSE_SESSION','LOCK_SESSION','CANCEL_SESSION','VALIDATE_LATENESS','MARK_EXCUSED','CREATE_PERMISSION','SUBMIT_PERMISSION','BEGIN_PERMISSION_REVIEW','APPROVE_PERMISSION','REJECT_PERMISSION','APPLY_PERMISSION','CANCEL_PERMISSION','REVOKE_PERMISSION_VALIDATION','CREATE_CORRECTION','SUBMIT_CORRECTION','BEGIN_CORRECTION_REVIEW','APPROVE_CORRECTION','REJECT_CORRECTION','APPLY_CORRECTION','CANCEL_CORRECTION','PROCESS_LATENESS','RECORD_NOTIFICATION','ACKNOWLEDGE_ALERT','CANCEL_ALERT');
create type academic.attendance_entity_type as enum ('ATTENDANCE_SESSION','ATTENDANCE_RECORD','LATENESS_COUNTER','LATENESS_ALERT','STUDENT_PERMISSION','PERMISSION_VALIDATION','ATTENDANCE_CORRECTION');
create type academic.attendance_event_type as enum ('ATTENDANCE_SESSION_CREATED','ATTENDANCE_SESSION_OPENED','ATTENDANCE_ROSTER_POPULATED','ATTENDANCE_RECORDED','BULK_ATTENDANCE_RECORDED','ATTENDANCE_SESSION_CLOSED','ATTENDANCE_SESSION_LOCKED','ATTENDANCE_SESSION_CANCELLED','LATENESS_RECORDED','LATENESS_VALIDATED','FIRST_PERIOD_LATENESS_COUNTED','LATENESS_ALERT_CREATED','LATENESS_NOTIFICATION_RECORDED','LATENESS_ALERT_ACKNOWLEDGED','PERMISSION_CREATED','PERMISSION_SUBMITTED','PERMISSION_APPROVED','PERMISSION_REJECTED','PERMISSION_APPLIED','ATTENDANCE_CORRECTION_CREATED','ATTENDANCE_CORRECTION_APPROVED','ATTENDANCE_CORRECTION_APPLIED','LATENESS_COUNTER_ADJUSTED','LATENESS_ALERT_CANCELLED','OPERATION_REJECTED');

create table academic.attendance_sessions(
 id uuid primary key default gen_random_uuid(), class_session_id uuid not null references academic.class_sessions(id) on delete restrict,
 academic_period_id uuid not null references academic.academic_periods(id) on delete restrict, group_id uuid not null references academic.groups(id) on delete restrict,
 academic_offering_id uuid not null references academic.academic_offerings(id) on delete restrict, teaching_assignment_id uuid not null references academic.teaching_assignments(id) on delete restrict,
 session_date date not null, starts_at timestamptz not null, ends_at timestamptz not null, status academic.attendance_session_status not null default 'DRAFT',
 expected_student_count integer not null default 0 check(expected_student_count>=0), opened_by_account_id uuid not null references core.accounts(id) on delete restrict,
 closed_by_account_id uuid references core.accounts(id) on delete restrict, cancelled_by_account_id uuid references core.accounts(id) on delete restrict,
 opened_at timestamptz not null default statement_timestamp(), closed_at timestamptz, cancelled_at timestamptz, created_at timestamptz not null default statement_timestamp(), updated_at timestamptz not null default statement_timestamp(),
 unique(class_session_id,session_date), check(starts_at<ends_at), check((status in ('CLOSED','LOCKED'))=(closed_at is not null)), check((status='CANCELLED')=(cancelled_at is not null))
);
create table academic.student_permissions(
 id uuid primary key default gen_random_uuid(), student_record_id uuid not null references academic.student_records(id) on delete restrict,
 academic_period_id uuid not null references academic.academic_periods(id) on delete restrict, permission_type academic.student_permission_type not null,
 applies_to_date date not null, starts_at timestamptz, ends_at timestamptz, status academic.student_permission_status not null default 'DRAFT', reason_code academic.permission_reason_code not null,
 requested_by_account_id uuid not null references core.accounts(id) on delete restrict, reviewed_by_account_id uuid references core.accounts(id) on delete restrict,
 approved_by_account_id uuid references core.accounts(id) on delete restrict, rejected_by_account_id uuid references core.accounts(id) on delete restrict,
 created_at timestamptz not null default statement_timestamp(), reviewed_at timestamptz, approved_at timestamptz, rejected_at timestamptz, cancelled_at timestamptz, updated_at timestamptz not null default statement_timestamp(),
 check(starts_at is null or ends_at is null or starts_at<ends_at)
);
create table academic.permission_validations(
 id uuid primary key default gen_random_uuid(), permission_id uuid not null references academic.student_permissions(id) on delete restrict,
 prefect_account_id uuid not null references core.accounts(id) on delete restrict, validation_status academic.permission_validation_status not null,
 validation_reason_code academic.permission_reason_code not null, validated_at timestamptz not null default statement_timestamp(), created_at timestamptz not null default statement_timestamp()
);
create table academic.attendance_records(
 id uuid primary key default gen_random_uuid(), attendance_session_id uuid not null references academic.attendance_sessions(id) on delete restrict,
 student_record_id uuid not null references academic.student_records(id) on delete restrict, period_enrollment_id uuid not null references academic.period_enrollments(id) on delete restrict,
 student_offering_enrollment_id uuid not null references academic.student_offering_enrollments(id) on delete restrict, attendance_status academic.attendance_status not null default 'NOT_RECORDED',
 is_first_period boolean not null, lateness_minutes integer, permission_id uuid references academic.student_permissions(id) on delete restrict,
 recorded_by_account_id uuid references core.accounts(id) on delete restrict, validated_by_prefect_account_id uuid references core.accounts(id) on delete restrict,
 recorded_at timestamptz, validated_at timestamptz, counted_at timestamptz, created_at timestamptz not null default statement_timestamp(), updated_at timestamptz not null default statement_timestamp(),
 unique(attendance_session_id,student_record_id), check(lateness_minutes is null or lateness_minutes>0),
 check((attendance_status='LATE' and lateness_minutes is not null) or (attendance_status<>'LATE' and lateness_minutes is null)),
 check((attendance_status='NOT_RECORDED')=(recorded_at is null))
);
create table academic.attendance_record_history(
 id uuid primary key default gen_random_uuid(), attendance_record_id uuid not null references academic.attendance_records(id) on delete restrict,
 previous_status academic.attendance_status, resulting_status academic.attendance_status not null, previous_lateness_minutes integer, resulting_lateness_minutes integer,
 change_type academic.attendance_history_change_type not null, reason_code academic.attendance_event_reason not null, actor_account_id uuid not null references core.accounts(id) on delete restrict,
 correction_id uuid, changed_at timestamptz not null default statement_timestamp(), created_at timestamptz not null default statement_timestamp()
);
create table academic.student_lateness_counters(
 id uuid primary key default gen_random_uuid(), student_record_id uuid not null references academic.student_records(id) on delete restrict,
 academic_period_id uuid not null references academic.academic_periods(id) on delete restrict, counter_type academic.lateness_counter_type not null,
 current_count integer not null default 0 check(current_count between 0 and 3), lifetime_count integer not null default 0 check(lifetime_count>=0),
 last_counted_attendance_record_id uuid references academic.attendance_records(id) on delete restrict, alert_sequence integer not null default 0 check(alert_sequence>=0),
 last_alert_id uuid, updated_at timestamptz not null default statement_timestamp(), created_at timestamptz not null default statement_timestamp(), unique(student_record_id,academic_period_id,counter_type)
);
create table academic.lateness_alerts(
 id uuid primary key default gen_random_uuid(), student_record_id uuid not null references academic.student_records(id) on delete restrict,
 academic_period_id uuid not null references academic.academic_periods(id) on delete restrict, alert_sequence integer not null check(alert_sequence>0), threshold_value integer not null default 4 check(threshold_value=4),
 triggering_attendance_record_id uuid not null references academic.attendance_records(id) on delete restrict, validated_lateness_count integer not null check(validated_lateness_count=4),
 status academic.lateness_alert_status not null default 'PENDING_NOTIFICATION', generated_by_account_id uuid not null references core.accounts(id) on delete restrict,
 acknowledged_by_account_id uuid references core.accounts(id) on delete restrict, notification_required boolean not null default true,
 generated_at timestamptz not null default statement_timestamp(), acknowledged_at timestamptz, cancelled_at timestamptz, created_at timestamptz not null default statement_timestamp(), updated_at timestamptz not null default statement_timestamp(),
 unique(student_record_id,academic_period_id,alert_sequence)
);
alter table academic.student_lateness_counters add constraint lateness_counter_last_alert_fk foreign key(last_alert_id) references academic.lateness_alerts(id) on delete restrict;
create table academic.attendance_corrections(
 id uuid primary key default gen_random_uuid(), attendance_record_id uuid not null references academic.attendance_records(id) on delete restrict,
 previous_status academic.attendance_status not null, resulting_status academic.attendance_status not null, previous_lateness_minutes integer, resulting_lateness_minutes integer,
 reason_code academic.attendance_correction_reason not null, status academic.attendance_correction_status not null default 'DRAFT',
 requested_by_account_id uuid not null references core.accounts(id) on delete restrict, approved_by_account_id uuid references core.accounts(id) on delete restrict,
 applied_by_account_id uuid references core.accounts(id) on delete restrict, idempotency_key text not null check(length(idempotency_key) between 8 and 120), request_fingerprint text not null check(request_fingerprint~'^[0-9a-f]{64}$'),
 requested_at timestamptz not null default statement_timestamp(), approved_at timestamptz, applied_at timestamptz, rejected_at timestamptz, cancelled_at timestamptz,
 created_at timestamptz not null default statement_timestamp(), updated_at timestamptz not null default statement_timestamp(), unique(requested_by_account_id,idempotency_key)
);
alter table academic.attendance_record_history add constraint attendance_history_correction_fk foreign key(correction_id) references academic.attendance_corrections(id) on delete restrict;
create table academic.attendance_commands(
 id uuid primary key default gen_random_uuid(), actor_account_id uuid not null references core.accounts(id) on delete restrict, command_type academic.attendance_command_type not null,
 idempotency_key text not null check(length(idempotency_key) between 8 and 120), request_fingerprint text not null check(request_fingerprint~'^[0-9a-f]{64}$'),
 status academic.attendance_command_status not null default 'IN_PROGRESS', result_entity_type academic.attendance_entity_type, result_entity_id uuid,
 created_at timestamptz not null default statement_timestamp(), completed_at timestamptz, unique(actor_account_id,command_type,idempotency_key)
);
create table academic.attendance_events(
 id uuid primary key default gen_random_uuid(), student_record_id uuid references academic.student_records(id) on delete restrict,
 attendance_session_id uuid references academic.attendance_sessions(id) on delete restrict, attendance_record_id uuid references academic.attendance_records(id) on delete restrict,
 entity_type academic.attendance_entity_type not null, entity_id uuid not null, event_type academic.attendance_event_type not null,
 actor_account_id uuid not null references core.accounts(id) on delete restrict, previous_status text, resulting_status text,
 reason_code academic.attendance_event_reason not null, idempotency_key text not null, correlation_id uuid, occurred_at timestamptz not null default statement_timestamp(),
 unique(actor_account_id,event_type,idempotency_key)
);

create index attendance_sessions_period_date_idx on academic.attendance_sessions(academic_period_id,session_date,status);
create index attendance_records_student_idx on academic.attendance_records(student_record_id,attendance_session_id);
create index attendance_permissions_student_date_idx on academic.student_permissions(student_record_id,applies_to_date,status);
create index attendance_events_entity_idx on academic.attendance_events(entity_type,entity_id,occurred_at);

do $$declare n text; begin foreach n in array array['attendance_sessions','attendance_records','attendance_record_history','student_lateness_counters','lateness_alerts','student_permissions','permission_validations','attendance_corrections','attendance_commands','attendance_events'] loop execute format('alter table academic.%I enable row level security',n); execute format('revoke all on table academic.%I from public,anon,authenticated',n); end loop; end$$;
revoke all on all sequences in schema academic from public,anon,authenticated;

create function academic.attendance_fingerprint(payload jsonb) returns text language sql immutable strict security invoker set search_path='' as $$select encode(extensions.digest(convert_to(payload::text,'UTF8'),'sha256'),'hex')$$;

create function academic.require_attendance_permission(permission_code text) returns uuid language plpgsql volatile security definer set search_path='' as $$
declare actor uuid; account core.accounts%rowtype; claims jsonb; role_codes text[]; allowed boolean:=false;
begin
 if permission_code not in ('academic.attendance.read','academic.attendance.manage','academic.attendance.validate','academic.permissions.read','academic.permissions.manage','academic.permissions.validate','academic.lateness.read','academic.lateness.validate','academic.lateness.notifications.record') then raise exception 'ACTOR_NOT_AUTHORIZED'; end if;
 actor:=auth.uid(); if actor is null then raise exception 'ACTOR_NOT_AUTHORIZED'; end if;
 select a.* into account from core.accounts a where a.auth_user_id=actor for share; if account.id is null or account.account_status<>'ACTIVE' then raise exception 'ACTOR_NOT_AUTHORIZED'; end if;
 claims:=coalesce(nullif(current_setting('request.jwt.claims',true),'')::jsonb,'{}'::jsonb);
 if claims->>'aal'<>'aal2' then raise exception 'AAL2_REQUIRED'; end if;
 if coalesce((claims->>'session_version')::integer,0)<>account.session_version then raise exception 'ACTOR_NOT_AUTHORIZED'; end if;
 select coalesce(array_agg(r.code),array[]::text[]) into role_codes from core.account_roles ar join core.roles r on r.id=ar.role_id where ar.account_id=account.id and ar.revoked_at is null;
 if role_codes&&array['SUPERADMIN'] then allowed:=true;
 elsif role_codes&&array['PREFECTURA'] then allowed:=permission_code in ('academic.attendance.read','academic.attendance.manage','academic.attendance.validate','academic.permissions.read','academic.permissions.manage','academic.permissions.validate','academic.lateness.read','academic.lateness.validate','academic.lateness.notifications.record');
 elsif role_codes&&array['ADMINISTRATIVO'] then allowed:=permission_code in ('academic.attendance.read','academic.attendance.manage','academic.permissions.read','academic.permissions.manage','academic.lateness.read');
 elsif role_codes&&array['CONTROL_ESCOLAR'] then allowed:=permission_code in ('academic.attendance.read','academic.attendance.manage','academic.permissions.read','academic.permissions.manage','academic.lateness.read');
 elsif role_codes&&array['DOCENTE'] then allowed:=permission_code in ('academic.attendance.read','academic.attendance.manage'); end if;
 if not allowed then raise exception 'ACTOR_NOT_AUTHORIZED'; end if; return account.id;
end$$;

create function academic.assert_attendance_session_teacher(actor uuid,attendance_session_id uuid) returns void language plpgsql stable security definer set search_path='' as $$
begin if exists(select 1 from core.account_roles ar join core.roles r on r.id=ar.role_id where ar.account_id=actor and ar.revoked_at is null and r.code='DOCENTE') and not exists(select 1 from academic.attendance_sessions s join academic.teaching_assignments a on a.id=s.teaching_assignment_id where s.id=attendance_session_id and a.teacher_account_id=actor and a.status='ACTIVE') then raise exception 'ACTOR_NOT_AUTHORIZED'; end if; end$$;

create function academic.begin_attendance_command(actor uuid,kind academic.attendance_command_type,operation_key text,payload jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare existing academic.attendance_commands%rowtype; fingerprint text:=academic.attendance_fingerprint(payload);
begin if operation_key is null or length(operation_key) not between 8 and 120 then raise exception 'IDEMPOTENCY_CONFLICT'; end if; perform pg_advisory_xact_lock(hashtextextended(actor::text||kind::text||operation_key,0)); select * into existing from academic.attendance_commands where actor_account_id=actor and command_type=kind and idempotency_key=operation_key for update; if existing.id is not null then if existing.request_fingerprint<>fingerprint then raise exception 'IDEMPOTENCY_CONFLICT'; end if; if existing.status='COMPLETED' then return existing.result_entity_id; else raise exception 'CONCURRENT_MODIFICATION'; end if; end if; insert into academic.attendance_commands(actor_account_id,command_type,idempotency_key,request_fingerprint) values(actor,kind,operation_key,fingerprint); return null; end$$;
create function academic.complete_attendance_command(actor uuid,kind academic.attendance_command_type,operation_key text,entity_type academic.attendance_entity_type,entity_id uuid) returns void language sql security definer set search_path='' as $$update academic.attendance_commands set status='COMPLETED',result_entity_type=entity_type,result_entity_id=entity_id,completed_at=statement_timestamp() where actor_account_id=actor and command_type=kind and idempotency_key=operation_key$$;
create function academic.append_attendance_event(student_id uuid,session_id uuid,record_id uuid,entity_type academic.attendance_entity_type,entity_id uuid,event_type academic.attendance_event_type,actor uuid,previous_status text,resulting_status text,reason academic.attendance_event_reason,operation_key text,correlation uuid default null) returns void language sql security definer set search_path='' as $$insert into academic.attendance_events(student_record_id,attendance_session_id,attendance_record_id,entity_type,entity_id,event_type,actor_account_id,previous_status,resulting_status,reason_code,idempotency_key,correlation_id) values(student_id,session_id,record_id,entity_type,entity_id,event_type,actor,previous_status,resulting_status,reason,operation_key,correlation) on conflict(actor_account_id,event_type,idempotency_key) do nothing$$;

create function academic.valid_attendance_session_transition(old academic.attendance_session_status,target academic.attendance_session_status) returns boolean language sql immutable security invoker set search_path='' as $$select (old,target) in (('DRAFT','OPEN'),('OPEN','CLOSED'),('OPEN','CANCELLED'),('CLOSED','LOCKED'),('DRAFT','CANCELLED'))$$;
create function academic.valid_student_permission_transition(old academic.student_permission_status,target academic.student_permission_status) returns boolean language sql immutable security invoker set search_path='' as $$select (old,target) in (('DRAFT','SUBMITTED'),('SUBMITTED','UNDER_REVIEW'),('UNDER_REVIEW','APPROVED'),('UNDER_REVIEW','REJECTED'),('APPROVED','APPLIED'),('DRAFT','CANCELLED'),('SUBMITTED','CANCELLED'),('SUBMITTED','EXPIRED'),('UNDER_REVIEW','EXPIRED'))$$;
create function academic.valid_attendance_correction_transition(old academic.attendance_correction_status,target academic.attendance_correction_status) returns boolean language sql immutable security invoker set search_path='' as $$select (old,target) in (('DRAFT','SUBMITTED'),('SUBMITTED','UNDER_REVIEW'),('UNDER_REVIEW','APPROVED'),('UNDER_REVIEW','REJECTED'),('APPROVED','APPLIED'),('DRAFT','CANCELLED'),('SUBMITTED','CANCELLED'))$$;

create function academic.guard_attendance_history() returns trigger language plpgsql security invoker set search_path='' as $$begin if tg_op='DELETE' then raise exception 'ATTENDANCE_HISTORY_IMMUTABLE'; end if; if tg_table_name='attendance_commands' then if old.status::text='IN_PROGRESS' and new.status::text='COMPLETED' then return new; end if; end if; if current_setting('academic.attendance_controlled_mutation',true)<>'on' then if tg_table_name in ('attendance_record_history','attendance_events','permission_validations') or old is distinct from new then raise exception 'ATTENDANCE_HISTORY_IMMUTABLE'; end if; end if; return new; end$$;
do $$declare n text; begin foreach n in array array['attendance_sessions','attendance_records','attendance_record_history','student_lateness_counters','lateness_alerts','student_permissions','permission_validations','attendance_corrections','attendance_commands','attendance_events'] loop execute format('create trigger %I_attendance_history before update or delete on academic.%I for each row execute function academic.guard_attendance_history()',n,n); end loop; end$$;

create function academic.guard_active_attendance_roster_dependencies() returns trigger language plpgsql security invoker set search_path='' as $$begin if old is distinct from new and exists(select 1 from academic.attendance_records ar join academic.attendance_sessions s on s.id=ar.attendance_session_id where ar.period_enrollment_id=old.id and s.status in ('DRAFT','OPEN')) then raise exception 'CONCURRENT_MODIFICATION'; end if; return new; end$$;
create trigger period_enrollment_attendance_dependency before update on academic.period_enrollments for each row execute function academic.guard_active_attendance_roster_dependencies();
create function academic.guard_active_attendance_group_assignment() returns trigger language plpgsql security invoker set search_path='' as $$begin if old is distinct from new and exists(select 1 from academic.attendance_records ar join academic.attendance_sessions s on s.id=ar.attendance_session_id where ar.period_enrollment_id=old.period_enrollment_id and s.status in ('DRAFT','OPEN')) then raise exception 'CONCURRENT_MODIFICATION'; end if; return new; end$$;
create trigger group_assignment_attendance_dependency before update on academic.student_group_assignments for each row execute function academic.guard_active_attendance_group_assignment();

create function academic.create_attendance_session(class_id uuid,attendance_date date,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$
declare actor uuid; prior uuid; cs academic.class_sessions%rowtype; gs academic.group_schedules%rowtype; offering academic.academic_offerings%rowtype; block academic.schedule_time_blocks%rowtype; created uuid; start_ts timestamptz; end_ts timestamptz;
begin actor:=academic.require_attendance_permission('academic.attendance.manage'); prior:=academic.begin_attendance_command(actor,'CREATE_SESSION',operation_key,jsonb_build_object('class_session',class_id,'date',attendance_date)); if prior is not null then return query select prior,'DRAFT'; return; end if;
 select * into cs from academic.class_sessions where id=class_id for update; if cs.id is null or cs.status not in ('PLANNED','ACTIVE') then raise exception 'CLASS_SESSION_NOT_AVAILABLE'; end if; select * into gs from academic.group_schedules where id=cs.group_schedule_id; select * into offering from academic.academic_offerings where id=cs.academic_offering_id; select * into block from academic.schedule_time_blocks where id=cs.time_block_id;
 if extract(isodow from attendance_date)::smallint<>cs.weekday then raise exception 'CLASS_SESSION_NOT_AVAILABLE'; end if; if attendance_date not between greatest(gs.effective_from,cs.valid_from) and least(gs.effective_to,cs.valid_to) then raise exception 'PERIOD_NOT_AVAILABLE'; end if; if not exists(select 1 from academic.academic_periods p where p.id=gs.academic_period_id and p.status in ('PLANNED','ACTIVE') and attendance_date between p.starts_on and p.ends_on) then raise exception 'PERIOD_NOT_AVAILABLE'; end if; if offering.status<>'ACTIVE' or not exists(select 1 from academic.teaching_assignments a where a.id=cs.teaching_assignment_id and a.academic_offering_id=cs.academic_offering_id and a.status='ACTIVE') then raise exception 'TEACHING_ASSIGNMENT_NOT_ACTIVE'; end if;
 start_ts:=attendance_date::timestamp+block.starts_at; end_ts:=attendance_date::timestamp+block.ends_at;
 insert into academic.attendance_sessions(class_session_id,academic_period_id,group_id,academic_offering_id,teaching_assignment_id,session_date,starts_at,ends_at,opened_by_account_id) values(cs.id,gs.academic_period_id,offering.group_id,offering.id,cs.teaching_assignment_id,attendance_date,start_ts,end_ts,actor) returning id into created;
 perform academic.complete_attendance_command(actor,'CREATE_SESSION',operation_key,'ATTENDANCE_SESSION',created); perform academic.append_attendance_event(null,created,null,'ATTENDANCE_SESSION',created,'ATTENDANCE_SESSION_CREATED',actor,null,'DRAFT','SESSION_OPERATION',operation_key,correlation); return query select created,'DRAFT';
end$$;

create function academic.populate_attendance_session_roster(attendance_session_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$
declare actor uuid; prior uuid; s academic.attendance_sessions%rowtype; first_period boolean; inserted integer;
begin actor:=academic.require_attendance_permission('academic.attendance.manage'); perform academic.assert_attendance_session_teacher(actor,attendance_session_id); prior:=academic.begin_attendance_command(actor,'POPULATE_ROSTER',operation_key,jsonb_build_object('session',attendance_session_id)); if prior is not null then return query select prior,'POPULATED'; return; end if; select * into s from academic.attendance_sessions where id=attendance_session_id for update; if s.id is null or s.status not in ('DRAFT','OPEN') then raise exception 'ATTENDANCE_SESSION_INVALID_STATE'; end if;
 select b.is_first_period into first_period from academic.class_sessions cs join academic.schedule_time_blocks b on b.id=cs.time_block_id where cs.id=s.class_session_id;
 insert into academic.attendance_records(attendance_session_id,student_record_id,period_enrollment_id,student_offering_enrollment_id,is_first_period)
 select s.id,pe.student_record_id,pe.id,soe.id,first_period from academic.period_enrollments pe join academic.student_offering_enrollments soe on soe.period_enrollment_id=pe.id and soe.academic_offering_id=s.academic_offering_id and soe.status='ACTIVE' join academic.student_group_assignments ga on ga.period_enrollment_id=pe.id and ga.group_id=s.group_id and ga.status='ACTIVE' join academic.student_records sr on sr.id=pe.student_record_id and sr.status='ACTIVE' where pe.academic_period_id=s.academic_period_id and pe.status='ACTIVE' on conflict on constraint attendance_records_attendance_session_id_student_record_id_key do nothing;
 get diagnostics inserted=row_count; perform set_config('academic.attendance_controlled_mutation','on',true); update academic.attendance_sessions set expected_student_count=(select count(*) from academic.attendance_records r where r.attendance_session_id=s.id),updated_at=statement_timestamp() where id=s.id; perform set_config('academic.attendance_controlled_mutation','off',true);
 perform academic.complete_attendance_command(actor,'POPULATE_ROSTER',operation_key,'ATTENDANCE_SESSION',s.id); perform academic.append_attendance_event(null,s.id,null,'ATTENDANCE_SESSION',s.id,'ATTENDANCE_ROSTER_POPULATED',actor,null,inserted::text,'SESSION_OPERATION',operation_key,correlation); return query select s.id,'POPULATED';
end$$;

create function academic.change_attendance_session_status(attendance_session_id uuid,target academic.attendance_session_status,kind academic.attendance_command_type,event academic.attendance_event_type,operation_key text,correlation uuid) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$
declare actor uuid; prior uuid; s academic.attendance_sessions%rowtype;
begin actor:=academic.require_attendance_permission('academic.attendance.manage'); perform academic.assert_attendance_session_teacher(actor,attendance_session_id); prior:=academic.begin_attendance_command(actor,kind,operation_key,jsonb_build_object('session',attendance_session_id,'target',target)); if prior is not null then return query select prior,target::text; return; end if; select * into s from academic.attendance_sessions where id=attendance_session_id for update; if s.id is null or not academic.valid_attendance_session_transition(s.status,target) then raise exception 'ATTENDANCE_SESSION_INVALID_STATE'; end if; if target='OPEN' and s.expected_student_count<>(select count(*) from academic.attendance_records ar where ar.attendance_session_id=s.id) then raise exception 'ATTENDANCE_ROSTER_ALREADY_POPULATED'; end if;
 perform set_config('academic.attendance_controlled_mutation','on',true); update academic.attendance_sessions set status=target,closed_by_account_id=case when target='CLOSED' then actor else closed_by_account_id end,cancelled_by_account_id=case when target='CANCELLED' then actor else cancelled_by_account_id end,closed_at=case when target='CLOSED' then statement_timestamp() else closed_at end,cancelled_at=case when target='CANCELLED' then statement_timestamp() else cancelled_at end,updated_at=statement_timestamp() where id=s.id; perform set_config('academic.attendance_controlled_mutation','off',true);
 perform academic.complete_attendance_command(actor,kind,operation_key,'ATTENDANCE_SESSION',s.id); perform academic.append_attendance_event(null,s.id,null,'ATTENDANCE_SESSION',s.id,event,actor,s.status::text,target::text,'SESSION_OPERATION',operation_key,correlation); return query select s.id,target::text;
end$$;
create function academic.open_attendance_session(id uuid,key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_attendance_session_status(id,'OPEN','OPEN_SESSION','ATTENDANCE_SESSION_OPENED',key,correlation)$$;
create function academic.close_attendance_session(id uuid,key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_attendance_session_status(id,'CLOSED','CLOSE_SESSION','ATTENDANCE_SESSION_CLOSED',key,correlation)$$;
create function academic.lock_attendance_session(id uuid,key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_attendance_session_status(id,'LOCKED','LOCK_SESSION','ATTENDANCE_SESSION_LOCKED',key,correlation)$$;
create function academic.cancel_attendance_session(id uuid,key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_attendance_session_status(id,'CANCELLED','CANCEL_SESSION','ATTENDANCE_SESSION_CANCELLED',key,correlation)$$;

create function academic.record_student_attendance(record_id uuid,new_status academic.attendance_status,minutes integer,permission_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$
declare actor uuid; prior uuid; r academic.attendance_records%rowtype; s academic.attendance_sessions%rowtype;
begin actor:=academic.require_attendance_permission('academic.attendance.manage'); prior:=academic.begin_attendance_command(actor,'RECORD_ATTENDANCE',operation_key,jsonb_build_object('record',record_id,'status',new_status,'minutes',minutes,'permission',permission_id)); if prior is not null then return query select prior,new_status::text; return; end if; select * into r from academic.attendance_records where id=record_id for update; if r.id is null then raise exception 'ATTENDANCE_RECORD_NOT_FOUND'; end if; select * into s from academic.attendance_sessions where id=r.attendance_session_id for update; perform academic.assert_attendance_session_teacher(actor,s.id); if s.status<>'OPEN' then raise exception 'ATTENDANCE_SESSION_CLOSED'; end if; if r.attendance_status<>'NOT_RECORDED' then raise exception 'ATTENDANCE_ALREADY_RECORDED'; end if; if new_status not in ('PRESENT','ABSENT','LATE','EXCUSED') then raise exception 'INVALID_ATTENDANCE_STATUS'; end if; if (new_status='LATE' and coalesce(minutes,0)<=0) then raise exception 'LATENESS_MINUTES_REQUIRED'; end if; if new_status<>'LATE' and minutes is not null then raise exception 'LATENESS_MINUTES_NOT_ALLOWED'; end if; if new_status='EXCUSED' and not exists(select 1 from academic.student_permissions p join academic.permission_validations v on v.permission_id=p.id and v.validation_status='APPROVED' where p.id=record_student_attendance.permission_id and p.student_record_id=r.student_record_id and p.applies_to_date=s.session_date and p.status in ('APPROVED','APPLIED')) then raise exception 'PERMISSION_NOT_APPLICABLE'; end if;
 perform set_config('academic.attendance_controlled_mutation','on',true); update academic.attendance_records set attendance_status=new_status,lateness_minutes=minutes,permission_id=record_student_attendance.permission_id,recorded_by_account_id=actor,recorded_at=statement_timestamp(),updated_at=statement_timestamp() where id=r.id; insert into academic.attendance_record_history(attendance_record_id,previous_status,resulting_status,previous_lateness_minutes,resulting_lateness_minutes,change_type,reason_code,actor_account_id) values(r.id,r.attendance_status,new_status,r.lateness_minutes,minutes,'INITIAL_CAPTURE','INITIAL_CAPTURE',actor); perform set_config('academic.attendance_controlled_mutation','off',true);
 perform academic.complete_attendance_command(actor,'RECORD_ATTENDANCE',operation_key,'ATTENDANCE_RECORD',r.id); perform academic.append_attendance_event(r.student_record_id,s.id,r.id,'ATTENDANCE_RECORD',r.id,case when new_status='LATE' then 'LATENESS_RECORDED'::academic.attendance_event_type else 'ATTENDANCE_RECORDED'::academic.attendance_event_type end,actor,r.attendance_status::text,new_status::text,'INITIAL_CAPTURE',operation_key,correlation); return query select r.id,new_status::text;
end$$;
create function academic.record_bulk_attendance(attendance_session_id uuid,items jsonb,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; item jsonb; rid uuid; begin actor:=academic.require_attendance_permission('academic.attendance.manage'); perform academic.assert_attendance_session_teacher(actor,attendance_session_id); prior:=academic.begin_attendance_command(actor,'RECORD_BULK_ATTENDANCE',operation_key,jsonb_build_object('session',attendance_session_id,'items',items)); if prior is not null then return query select prior,'RECORDED'; return; end if; for item in select value from jsonb_array_elements(items) loop rid:=(item->>'record_id')::uuid; perform * from academic.record_student_attendance(rid,(item->>'status')::academic.attendance_status,nullif(item->>'lateness_minutes','')::integer,nullif(item->>'permission_id','')::uuid,operation_key||'_'||substr(rid::text,1,8),correlation); end loop; perform academic.complete_attendance_command(actor,'RECORD_BULK_ATTENDANCE',operation_key,'ATTENDANCE_SESSION',attendance_session_id); perform academic.append_attendance_event(null,attendance_session_id,null,'ATTENDANCE_SESSION',attendance_session_id,'BULK_ATTENDANCE_RECORDED',actor,null,'RECORDED','INITIAL_CAPTURE',operation_key,correlation); return query select attendance_session_id,'RECORDED'; end$$;

create function academic.process_first_period_lateness(record_id uuid,actor uuid,operation_key text,correlation uuid default null) returns uuid language plpgsql security definer set search_path='' as $$
declare r academic.attendance_records%rowtype; s academic.attendance_sessions%rowtype; counter academic.student_lateness_counters%rowtype; alert_id uuid; next_count integer;
begin select * into r from academic.attendance_records where id=record_id for update; if r.id is null or r.attendance_status<>'LATE' or not r.is_first_period or r.validated_at is null then raise exception 'FIRST_PERIOD_MISMATCH'; end if; if r.counted_at is not null then return null; end if; select * into s from academic.attendance_sessions where id=r.attendance_session_id; perform pg_advisory_xact_lock(hashtextextended(r.student_record_id::text||s.academic_period_id::text,0)); insert into academic.student_lateness_counters(student_record_id,academic_period_id,counter_type) values(r.student_record_id,s.academic_period_id,'FIRST_PERIOD_VALIDATED') on conflict do nothing; select * into counter from academic.student_lateness_counters where student_record_id=r.student_record_id and academic_period_id=s.academic_period_id and counter_type='FIRST_PERIOD_VALIDATED' for update; next_count:=counter.current_count+1;
 perform set_config('academic.attendance_controlled_mutation','on',true); update academic.attendance_records set counted_at=statement_timestamp(),updated_at=statement_timestamp() where id=r.id; if next_count=4 then insert into academic.lateness_alerts(student_record_id,academic_period_id,alert_sequence,triggering_attendance_record_id,validated_lateness_count,generated_by_account_id) values(r.student_record_id,s.academic_period_id,counter.alert_sequence+1,r.id,4,actor) returning id into alert_id; update academic.student_lateness_counters set current_count=0,lifetime_count=lifetime_count+1,alert_sequence=alert_sequence+1,last_counted_attendance_record_id=r.id,last_alert_id=alert_id,updated_at=statement_timestamp() where id=counter.id; else update academic.student_lateness_counters set current_count=next_count,lifetime_count=lifetime_count+1,last_counted_attendance_record_id=r.id,updated_at=statement_timestamp() where id=counter.id; end if; perform set_config('academic.attendance_controlled_mutation','off',true);
 perform academic.append_attendance_event(r.student_record_id,s.id,r.id,'LATENESS_COUNTER',counter.id,'FIRST_PERIOD_LATENESS_COUNTED',actor,null,next_count::text,'INSTITUTIONAL_VALIDATION',operation_key,correlation); if alert_id is not null then perform academic.append_attendance_event(r.student_record_id,s.id,r.id,'LATENESS_ALERT',alert_id,'LATENESS_ALERT_CREATED',actor,null,'PENDING_NOTIFICATION','INSTITUTIONAL_VALIDATION',operation_key||'_ALERT',correlation); end if; return alert_id;
end$$;
create function academic.validate_student_lateness(record_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; r academic.attendance_records%rowtype; alert_id uuid; begin actor:=academic.require_attendance_permission('academic.lateness.validate'); if not exists(select 1 from core.account_roles ar join core.roles ro on ro.id=ar.role_id where ar.account_id=actor and ar.revoked_at is null and ro.code in ('PREFECTURA','SUPERADMIN')) then raise exception 'PREFECTURE_ROLE_REQUIRED'; end if; prior:=academic.begin_attendance_command(actor,'VALIDATE_LATENESS',operation_key,jsonb_build_object('record',record_id)); if prior is not null then return query select prior,'VALIDATED'; return; end if; select * into r from academic.attendance_records where id=record_id for update; if r.id is null or r.attendance_status<>'LATE' then raise exception 'ATTENDANCE_RECORD_NOT_FOUND'; end if; if r.validated_at is not null then raise exception 'LATENESS_ALREADY_VALIDATED'; end if; perform set_config('academic.attendance_controlled_mutation','on',true); update academic.attendance_records set validated_by_prefect_account_id=actor,validated_at=statement_timestamp(),updated_at=statement_timestamp() where id=r.id; perform set_config('academic.attendance_controlled_mutation','off',true); alert_id:=academic.process_first_period_lateness(r.id,actor,operation_key,correlation); perform academic.complete_attendance_command(actor,'VALIDATE_LATENESS',operation_key,'ATTENDANCE_RECORD',r.id); perform academic.append_attendance_event(r.student_record_id,r.attendance_session_id,r.id,'ATTENDANCE_RECORD',r.id,'LATENESS_VALIDATED',actor,'LATE','LATE','INSTITUTIONAL_VALIDATION',operation_key||'_VALID',correlation); return query select r.id,'VALIDATED'; end$$;

create function academic.create_student_permission(student_id uuid,period_id uuid,kind academic.student_permission_type,applies_on date,start_time timestamptz,end_time timestamptz,reason academic.permission_reason_code,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; created uuid; begin actor:=academic.require_attendance_permission('academic.permissions.manage'); prior:=academic.begin_attendance_command(actor,'CREATE_PERMISSION',operation_key,jsonb_build_object('student',student_id,'period',period_id,'kind',kind,'date',applies_on,'start',start_time,'end',end_time,'reason',reason)); if prior is not null then return query select prior,'DRAFT'; return; end if; if not exists(select 1 from academic.period_enrollments e where e.student_record_id=student_id and e.academic_period_id=period_id and e.status='ACTIVE') then raise exception 'STUDENT_NOT_ENROLLED'; end if; insert into academic.student_permissions(student_record_id,academic_period_id,permission_type,applies_to_date,starts_at,ends_at,reason_code,requested_by_account_id) values(student_id,period_id,kind,applies_on,start_time,end_time,reason,actor) returning id into created; perform academic.complete_attendance_command(actor,'CREATE_PERMISSION',operation_key,'STUDENT_PERMISSION',created); perform academic.append_attendance_event(student_id,null,null,'STUDENT_PERMISSION',created,'PERMISSION_CREATED',actor,null,'DRAFT','SESSION_OPERATION',operation_key,correlation); return query select created,'DRAFT'; end$$;
create function academic.change_student_permission_status(permission_id uuid,target academic.student_permission_status,kind academic.attendance_command_type,event academic.attendance_event_type,permission_code text,operation_key text,correlation uuid) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; p academic.student_permissions%rowtype; begin actor:=academic.require_attendance_permission(permission_code); prior:=academic.begin_attendance_command(actor,kind,operation_key,jsonb_build_object('permission',permission_id,'target',target)); if prior is not null then return query select prior,target::text; return; end if; select * into p from academic.student_permissions where id=permission_id for update; if p.id is null or not academic.valid_student_permission_transition(p.status,target) then raise exception 'PERMISSION_INVALID_STATE'; end if; if target='APPROVED' and not exists(select 1 from core.account_roles ar join core.roles r on r.id=ar.role_id where ar.account_id=actor and ar.revoked_at is null and r.code in ('PREFECTURA','SUPERADMIN')) then raise exception 'PREFECTURE_ROLE_REQUIRED'; end if; perform set_config('academic.attendance_controlled_mutation','on',true); update academic.student_permissions set status=target,reviewed_by_account_id=case when target='UNDER_REVIEW' then actor else reviewed_by_account_id end,approved_by_account_id=case when target='APPROVED' then actor else approved_by_account_id end,rejected_by_account_id=case when target='REJECTED' then actor else rejected_by_account_id end,reviewed_at=case when target='UNDER_REVIEW' then statement_timestamp() else reviewed_at end,approved_at=case when target='APPROVED' then statement_timestamp() else approved_at end,rejected_at=case when target='REJECTED' then statement_timestamp() else rejected_at end,cancelled_at=case when target='CANCELLED' then statement_timestamp() else cancelled_at end,updated_at=statement_timestamp() where id=p.id; if target in ('APPROVED','REJECTED') then insert into academic.permission_validations(permission_id,prefect_account_id,validation_status,validation_reason_code) values(p.id,actor,target::text::academic.permission_validation_status,p.reason_code); end if; perform set_config('academic.attendance_controlled_mutation','off',true); perform academic.complete_attendance_command(actor,kind,operation_key,'STUDENT_PERMISSION',p.id); perform academic.append_attendance_event(p.student_record_id,null,null,'STUDENT_PERMISSION',p.id,event,actor,p.status::text,target::text,case when target='APPROVED' then 'APPROVED_PERMISSION'::academic.attendance_event_reason else 'SESSION_OPERATION'::academic.attendance_event_reason end,operation_key,correlation); return query select p.id,target::text; end$$;
create function academic.submit_student_permission(id uuid,key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_student_permission_status(id,'SUBMITTED','SUBMIT_PERMISSION','PERMISSION_SUBMITTED','academic.permissions.manage',key,correlation)$$;
create function academic.begin_permission_review(id uuid,key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_student_permission_status(id,'UNDER_REVIEW','BEGIN_PERMISSION_REVIEW','PERMISSION_SUBMITTED','academic.permissions.validate',key,correlation)$$;
create function academic.approve_student_permission(id uuid,key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_student_permission_status(id,'APPROVED','APPROVE_PERMISSION','PERMISSION_APPROVED','academic.permissions.validate',key,correlation)$$;
create function academic.reject_student_permission(id uuid,key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_student_permission_status(id,'REJECTED','REJECT_PERMISSION','PERMISSION_REJECTED','academic.permissions.validate',key,correlation)$$;
create function academic.apply_student_permission(id uuid,key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_student_permission_status(id,'APPLIED','APPLY_PERMISSION','PERMISSION_APPLIED','academic.permissions.manage',key,correlation)$$;
create function academic.cancel_student_permission(id uuid,key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_student_permission_status(id,'CANCELLED','CANCEL_PERMISSION','PERMISSION_REJECTED','academic.permissions.manage',key,correlation)$$;
create function academic.revoke_permission_validation(validation_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; v academic.permission_validations%rowtype; begin actor:=academic.require_attendance_permission('academic.permissions.validate'); if not exists(select 1 from core.account_roles ar join core.roles r on r.id=ar.role_id where ar.account_id=actor and ar.revoked_at is null and r.code in ('PREFECTURA','SUPERADMIN')) then raise exception 'PREFECTURE_ROLE_REQUIRED'; end if; select * into v from academic.permission_validations where id=validation_id for update; if v.id is null or v.validation_status<>'APPROVED' then raise exception 'PERMISSION_INVALID_STATE'; end if; perform set_config('academic.attendance_controlled_mutation','on',true); insert into academic.permission_validations(permission_id,prefect_account_id,validation_status,validation_reason_code) values(v.permission_id,actor,'REVOKED',v.validation_reason_code); perform set_config('academic.attendance_controlled_mutation','off',true); return query select v.permission_id,'REVOKED'; end$$;

create function academic.mark_attendance_excused(record_id uuid,permission_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; r academic.attendance_records%rowtype; p academic.student_permissions%rowtype; begin actor:=academic.require_attendance_permission('academic.attendance.validate'); select * into r from academic.attendance_records where id=record_id for update; select * into p from academic.student_permissions where id=permission_id for update; if r.id is null or p.id is null or p.student_record_id<>r.student_record_id or p.status not in ('APPROVED','APPLIED') or not exists(select 1 from academic.permission_validations v where v.permission_id=p.id and v.validation_status='APPROVED' and not exists(select 1 from academic.permission_validations x where x.permission_id=p.id and x.validation_status='REVOKED' and x.validated_at>v.validated_at)) then raise exception 'PERMISSION_NOT_APPLICABLE'; end if; perform set_config('academic.attendance_controlled_mutation','on',true); update academic.attendance_records set attendance_status='EXCUSED',lateness_minutes=null,permission_id=p.id,updated_at=statement_timestamp() where id=r.id; insert into academic.attendance_record_history(attendance_record_id,previous_status,resulting_status,previous_lateness_minutes,resulting_lateness_minutes,change_type,reason_code,actor_account_id) values(r.id,r.attendance_status,'EXCUSED',r.lateness_minutes,null,'PERMISSION_APPLIED','APPROVED_PERMISSION',actor); perform set_config('academic.attendance_controlled_mutation','off',true); perform academic.append_attendance_event(r.student_record_id,r.attendance_session_id,r.id,'ATTENDANCE_RECORD',r.id,'PERMISSION_APPLIED',actor,r.attendance_status::text,'EXCUSED','APPROVED_PERMISSION',operation_key,correlation); return query select r.id,'EXCUSED'; end$$;

create function academic.create_attendance_correction(record_id uuid,resulting academic.attendance_status,resulting_minutes integer,reason academic.attendance_correction_reason,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; r academic.attendance_records%rowtype; created uuid; fingerprint text; begin actor:=academic.require_attendance_permission('academic.attendance.manage'); prior:=academic.begin_attendance_command(actor,'CREATE_CORRECTION',operation_key,jsonb_build_object('record',record_id,'status',resulting,'minutes',resulting_minutes,'reason',reason)); if prior is not null then return query select prior,'DRAFT'; return; end if; select * into r from academic.attendance_records where id=record_id for update; if r.id is null or r.attendance_status='NOT_RECORDED' then raise exception 'ATTENDANCE_RECORD_NOT_FOUND'; end if; if (resulting='LATE' and coalesce(resulting_minutes,0)<=0) or (resulting<>'LATE' and resulting_minutes is not null) then raise exception 'INVALID_ATTENDANCE_STATUS'; end if; fingerprint:=academic.attendance_fingerprint(jsonb_build_object('record',record_id,'status',resulting,'minutes',resulting_minutes,'reason',reason)); insert into academic.attendance_corrections(attendance_record_id,previous_status,resulting_status,previous_lateness_minutes,resulting_lateness_minutes,reason_code,requested_by_account_id,idempotency_key,request_fingerprint) values(r.id,r.attendance_status,resulting,r.lateness_minutes,resulting_minutes,reason,actor,operation_key,fingerprint) returning id into created; perform academic.complete_attendance_command(actor,'CREATE_CORRECTION',operation_key,'ATTENDANCE_CORRECTION',created); perform academic.append_attendance_event(r.student_record_id,r.attendance_session_id,r.id,'ATTENDANCE_CORRECTION',created,'ATTENDANCE_CORRECTION_CREATED',actor,null,'DRAFT','CONTROLLED_CORRECTION',operation_key,correlation); return query select created,'DRAFT'; end$$;
create function academic.change_attendance_correction_status(correction_id uuid,target academic.attendance_correction_status,kind academic.attendance_command_type,event academic.attendance_event_type,operation_key text,correlation uuid) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; prior uuid; c academic.attendance_corrections%rowtype; r academic.attendance_records%rowtype; begin actor:=academic.require_attendance_permission('academic.attendance.manage'); prior:=academic.begin_attendance_command(actor,kind,operation_key,jsonb_build_object('correction',correction_id,'target',target)); if prior is not null then return query select prior,target::text; return; end if; select * into c from academic.attendance_corrections where id=correction_id for update; if c.id is null or not academic.valid_attendance_correction_transition(c.status,target) then raise exception 'CORRECTION_INVALID_STATE'; end if; select * into r from academic.attendance_records where id=c.attendance_record_id for update; if target='APPLIED' and exists(select 1 from academic.attendance_sessions s where s.id=r.attendance_session_id and s.status='LOCKED') then raise exception 'ATTENDANCE_SESSION_LOCKED'; end if; perform set_config('academic.attendance_controlled_mutation','on',true); update academic.attendance_corrections set status=target,approved_by_account_id=case when target='APPROVED' then actor else approved_by_account_id end,applied_by_account_id=case when target='APPLIED' then actor else applied_by_account_id end,approved_at=case when target='APPROVED' then statement_timestamp() else approved_at end,applied_at=case when target='APPLIED' then statement_timestamp() else applied_at end,rejected_at=case when target='REJECTED' then statement_timestamp() else rejected_at end,cancelled_at=case when target='CANCELLED' then statement_timestamp() else cancelled_at end,updated_at=statement_timestamp() where id=c.id; if target='APPLIED' then if r.attendance_status='LATE' and r.counted_at is not null and c.resulting_status<>'LATE' then update academic.student_lateness_counters lc set current_count=greatest(0,lc.current_count-1),updated_at=statement_timestamp() from academic.attendance_sessions s where s.id=r.attendance_session_id and lc.student_record_id=r.student_record_id and lc.academic_period_id=s.academic_period_id and lc.counter_type='FIRST_PERIOD_VALIDATED'; end if; update academic.attendance_records set attendance_status=c.resulting_status,lateness_minutes=c.resulting_lateness_minutes,validated_by_prefect_account_id=null,validated_at=null,counted_at=null,updated_at=statement_timestamp() where id=r.id; insert into academic.attendance_record_history(attendance_record_id,previous_status,resulting_status,previous_lateness_minutes,resulting_lateness_minutes,change_type,reason_code,actor_account_id,correction_id) values(r.id,r.attendance_status,c.resulting_status,r.lateness_minutes,c.resulting_lateness_minutes,'CONTROLLED_CORRECTION','CONTROLLED_CORRECTION',actor,c.id); end if; perform set_config('academic.attendance_controlled_mutation','off',true); perform academic.complete_attendance_command(actor,kind,operation_key,'ATTENDANCE_CORRECTION',c.id); perform academic.append_attendance_event(r.student_record_id,r.attendance_session_id,r.id,'ATTENDANCE_CORRECTION',c.id,event,actor,c.status::text,target::text,'CONTROLLED_CORRECTION',operation_key,correlation); return query select c.id,target::text; end$$;
create function academic.submit_attendance_correction(id uuid,key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_attendance_correction_status(id,'SUBMITTED','SUBMIT_CORRECTION','ATTENDANCE_CORRECTION_CREATED',key,correlation)$$;
create function academic.begin_attendance_correction_review(id uuid,key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_attendance_correction_status(id,'UNDER_REVIEW','BEGIN_CORRECTION_REVIEW','ATTENDANCE_CORRECTION_CREATED',key,correlation)$$;
create function academic.approve_attendance_correction(id uuid,key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_attendance_correction_status(id,'APPROVED','APPROVE_CORRECTION','ATTENDANCE_CORRECTION_APPROVED',key,correlation)$$;
create function academic.reject_attendance_correction(id uuid,key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_attendance_correction_status(id,'REJECTED','REJECT_CORRECTION','ATTENDANCE_CORRECTION_APPROVED',key,correlation)$$;
create function academic.apply_attendance_correction(id uuid,key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_attendance_correction_status(id,'APPLIED','APPLY_CORRECTION','ATTENDANCE_CORRECTION_APPLIED',key,correlation)$$;
create function academic.cancel_attendance_correction(id uuid,key text,correlation uuid default null) returns table(entity_id uuid,status text) language sql security definer set search_path='' as $$select * from academic.change_attendance_correction_status(id,'CANCELLED','CANCEL_CORRECTION','ATTENDANCE_CORRECTION_CREATED',key,correlation)$$;

create function academic.record_lateness_notification(alert_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; a academic.lateness_alerts%rowtype; begin actor:=academic.require_attendance_permission('academic.lateness.notifications.record'); select * into a from academic.lateness_alerts where id=alert_id for update; if a.id is null or a.status<>'PENDING_NOTIFICATION' then raise exception 'LATENESS_ALERT_ALREADY_EXISTS'; end if; perform set_config('academic.attendance_controlled_mutation','on',true); update academic.lateness_alerts set status='NOTIFICATION_RECORDED',notification_required=false,updated_at=statement_timestamp() where id=a.id; perform set_config('academic.attendance_controlled_mutation','off',true); perform academic.append_attendance_event(a.student_record_id,null,a.triggering_attendance_record_id,'LATENESS_ALERT',a.id,'LATENESS_NOTIFICATION_RECORDED',actor,a.status::text,'NOTIFICATION_RECORDED','NOTIFICATION_RECORD',operation_key,correlation); return query select a.id,'NOTIFICATION_RECORDED'; end$$;
create function academic.acknowledge_lateness_alert(alert_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; a academic.lateness_alerts%rowtype; begin actor:=academic.require_attendance_permission('academic.lateness.notifications.record'); select * into a from academic.lateness_alerts where id=alert_id for update; if a.id is null or a.status<>'NOTIFICATION_RECORDED' then raise exception 'LATENESS_ALERT_ALREADY_EXISTS'; end if; perform set_config('academic.attendance_controlled_mutation','on',true); update academic.lateness_alerts set status='ACKNOWLEDGED',acknowledged_by_account_id=actor,acknowledged_at=statement_timestamp(),updated_at=statement_timestamp() where id=a.id; perform set_config('academic.attendance_controlled_mutation','off',true); perform academic.append_attendance_event(a.student_record_id,null,a.triggering_attendance_record_id,'LATENESS_ALERT',a.id,'LATENESS_ALERT_ACKNOWLEDGED',actor,a.status::text,'ACKNOWLEDGED','NOTIFICATION_RECORD',operation_key,correlation); return query select a.id,'ACKNOWLEDGED'; end$$;
create function academic.cancel_lateness_alert_after_correction(alert_id uuid,operation_key text,correlation uuid default null) returns table(entity_id uuid,status text) language plpgsql security definer set search_path='' as $$declare actor uuid; a academic.lateness_alerts%rowtype; begin actor:=academic.require_attendance_permission('academic.attendance.manage'); select * into a from academic.lateness_alerts where id=alert_id for update; if a.id is null or a.status<>'PENDING_NOTIFICATION' then raise exception 'CORRECTION_INVALID_STATE'; end if; if not exists(select 1 from academic.attendance_corrections c where c.attendance_record_id=a.triggering_attendance_record_id and c.status='APPLIED' and c.resulting_status<>'LATE') then raise exception 'CORRECTION_INVALID_STATE'; end if; perform set_config('academic.attendance_controlled_mutation','on',true); update academic.lateness_alerts set status='CANCELLED',cancelled_at=statement_timestamp(),notification_required=false,updated_at=statement_timestamp() where id=a.id; perform set_config('academic.attendance_controlled_mutation','off',true); perform academic.append_attendance_event(a.student_record_id,null,a.triggering_attendance_record_id,'LATENESS_ALERT',a.id,'LATENESS_ALERT_CANCELLED',actor,a.status::text,'CANCELLED','CONTROLLED_CORRECTION',operation_key,correlation); return query select a.id,'CANCELLED'; end$$;

create function academic.get_attendance_session_summary(p_attendance_session_id uuid) returns table(expected_count integer,recorded_count integer,present_count integer,absent_count integer,late_count integer,excused_count integer,not_recorded_count integer) language plpgsql stable security definer set search_path='' as $$begin perform academic.require_attendance_permission('academic.attendance.read'); return query select s.expected_student_count,count(*) filter(where r.attendance_status<>'NOT_RECORDED')::integer,count(*) filter(where r.attendance_status='PRESENT')::integer,count(*) filter(where r.attendance_status='ABSENT')::integer,count(*) filter(where r.attendance_status='LATE')::integer,count(*) filter(where r.attendance_status='EXCUSED')::integer,count(*) filter(where r.attendance_status='NOT_RECORDED')::integer from academic.attendance_sessions s left join academic.attendance_records r on r.attendance_session_id=s.id where s.id=p_attendance_session_id group by s.expected_student_count; end$$;
create function academic.get_student_attendance_summary(student_id uuid,period_id uuid) returns table(total_sessions integer,present_count integer,absent_count integer,late_count integer,excused_count integer) language plpgsql stable security definer set search_path='' as $$begin perform academic.require_attendance_permission('academic.attendance.read'); return query select count(*)::integer,count(*) filter(where r.attendance_status='PRESENT')::integer,count(*) filter(where r.attendance_status='ABSENT')::integer,count(*) filter(where r.attendance_status='LATE')::integer,count(*) filter(where r.attendance_status='EXCUSED')::integer from academic.attendance_records r join academic.attendance_sessions s on s.id=r.attendance_session_id where r.student_record_id=student_id and s.academic_period_id=period_id; end$$;
create function academic.get_student_lateness_summary(student_id uuid,period_id uuid) returns table(current_count integer,lifetime_count integer,alert_sequence integer,pending_alert_count integer) language plpgsql stable security definer set search_path='' as $$begin perform academic.require_attendance_permission('academic.lateness.read'); return query select coalesce(c.current_count,0),coalesce(c.lifetime_count,0),coalesce(c.alert_sequence,0),(select count(*)::integer from academic.lateness_alerts a where a.student_record_id=student_id and a.academic_period_id=period_id and a.status='PENDING_NOTIFICATION') from academic.student_lateness_counters c where c.student_record_id=student_id and c.academic_period_id=period_id and c.counter_type='FIRST_PERIOD_VALIDATED'; end$$;
create function academic.validate_attendance_session_integrity(p_attendance_session_id uuid) returns table(valid boolean,expected_count integer,roster_count integer,invalid_record_count integer) language plpgsql stable security definer set search_path='' as $$begin perform academic.require_attendance_permission('academic.attendance.read'); return query select s.expected_student_count=count(r.id) and count(*) filter(where pe.status<>'ACTIVE' or soe.status<>'ACTIVE')=0,s.expected_student_count,count(r.id)::integer,count(*) filter(where pe.status<>'ACTIVE' or soe.status<>'ACTIVE')::integer from academic.attendance_sessions s left join academic.attendance_records r on r.attendance_session_id=s.id left join academic.period_enrollments pe on pe.id=r.period_enrollment_id left join academic.student_offering_enrollments soe on soe.id=r.student_offering_enrollment_id where s.id=p_attendance_session_id group by s.expected_student_count; end$$;

revoke all on all functions in schema academic from public,anon,authenticated;
alter default privileges in schema academic revoke all on tables from public,anon,authenticated;
alter default privileges in schema academic revoke all on sequences from public,anon,authenticated;
alter default privileges in schema academic revoke execute on functions from public,anon,authenticated;

commit;
